const toTeam = (n) => { const t = String(n || '').trim(); return /^ال/.test(t) ? `لل${t.slice(2)}` : /^[\u0600-\u06FF]/.test(t) ? `ل${t}` : `لـ ${t}`; };
/* the letter on a player's avatar: «أبو سعيد» is س and «أم العبد» is ع, so a table of kunyas isn't all أ */
const initial = (name) => { let t = String(name || '').trim(); const k = /^(?:أبو|ابو|أم|ام)\s+(\S.*)$/.exec(t); if (k) t = k[1]; if (/^ال/.test(t) && t.length > 3) t = t.slice(2); return [...t][0] || '؟'; };
const avatar = (color, label, cls = '') => `<span class="avatar ${cls}" style="${cvar(color)}"><b class="av-l">${esc(initial(label))}</b></span>`;
