/* ---------- storage (per-browser convenience only) ---------- */
const Store = {
  KEY: 'lamma.v1',
  d: null,
  fresh() { return { played: {}, history: [], custom: [], prefs: { sound: true, vib: true, night: false }, days: [], resume: null, roster: [], cfg: {} }; },
  load() {
    this.d = this.fresh();
    try {
      const raw = localStorage.getItem(this.KEY);
      if (raw) { const o = JSON.parse(raw); if (o && typeof o === 'object') Object.assign(this.d, o); }
    } catch (e) { /* storage blocked: run in memory */ }
    this.d.prefs = Object.assign({ sound: true, vib: true, night: false }, this.d.prefs || {});
    delete this.d.prefs.music; // the background rhythm is gone (no music in the app)
    for (const k of ['history', 'custom', 'days', 'roster']) if (!Array.isArray(this.d[k])) this.d[k] = [];
    if (!this.d.played || typeof this.d.played !== 'object') this.d.played = {};
    if (!this.d.cfg || typeof this.d.cfg !== 'object') this.d.cfg = {};
  },
  save() { clearTimeout(this._t); try { localStorage.setItem(this.KEY, JSON.stringify(this.d)); } catch (e) { /* ignore */ } },
  soon() { clearTimeout(this._t); this._t = setTimeout(() => this.save(), 300); },
  flush() { if (this._t) { clearTimeout(this._t); this._t = null; this.save(); } },
  record(entry, noCount) {
    this.d.history.unshift(Object.assign({ at: Date.now() }, entry));
    this.d.history = this.d.history.slice(0, 60);
    const k = dayKey();
    if (!this.d.days.includes(k)) this.d.days.push(k);
    this.d.days = this.d.days.slice(-400);
    this.save();
    if (!noCount && typeof Counter !== 'undefined') Counter.game(entry && entry.game);
  },
  streak() {
    const set = new Set(this.d.days); let n = 0; const d = new Date();
    if (!set.has(dayKey(d))) d.setDate(d.getDate() - 1);
    while (set.has(dayKey(d))) { n++; d.setDate(d.getDate() - 1); }
    return n;
  },
};

/* ---------- one shared countdown ---------- */
const Timer = {
  id: null, end: 0, total: 0, left: 0, paused: false, onEnd: null, last: null,
  start(sec, onEnd) {
    this.stop(); this.total = sec; this.left = sec; this.end = Date.now() + sec * 1000;
    this.paused = false; this.onEnd = onEnd || null; this.last = null;
    this.id = setInterval(() => this.tick(), 200); this.paint();
  },
  tick() {
    if (this.paused) return;
    this.left = Math.max(0, (this.end - Date.now()) / 1000);
    const s = Math.ceil(this.left);
    if (s !== this.last) { this.last = s; if (s <= 5 && s > 0) Sfx.play('tick'); }
    this.paint();
    if (this.left <= 0) { const cb = this.onEnd; this.stop(); Sfx.play('end'); buzz([180, 90, 180]); if (cb) cb(); }
  },
  pause() { if (!this.id || this.paused) return; this.paused = true; this.left = Math.max(0, (this.end - Date.now()) / 1000); this.paint(); },
  resume() { if (!this.id || !this.paused) return; this.paused = false; this.end = Date.now() + this.left * 1000; this.paint(); },
  toggle() { this.paused ? this.resume() : this.pause(); },
  add(sec) { if (!this.id) return; this.end += sec * 1000; this.left += sec; this.total = Math.max(this.total, this.left); this.paint(); },
  stop() { clearInterval(this.id); this.id = null; this.paused = false; },
  running() { return !!this.id; },
  paint() {
    const s = Math.ceil(this.left), frac = this.total ? clamp(this.left / this.total, 0, 1) : 0;
    $$('[data-timer]').forEach((el) => {
      el.style.setProperty('--p', frac.toFixed(4));
      const t = el.querySelector('.tm-num');
      if (t) t.textContent = !this.id && !this.left ? '0' : s >= 60 ? `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}` : String(s);
      el.classList.toggle('low', !!this.id && s <= 5);
      el.classList.toggle('paused', this.paused);
      el.classList.toggle('idle', !this.id && this.left <= 0);
    });
  },
};
const timerRing = (cls = '') => `<div class="tm ${cls}" data-timer role="timer" aria-live="off"><svg viewBox="0 0 44 44" aria-hidden="true"><circle class="tm-bg" cx="22" cy="22" r="19"/><circle class="tm-fg" cx="22" cy="22" r="19" pathLength="100"/></svg><span class="tm-num"></span></div>`;

/* ---------- toast, modal, confirm, confetti, count-up ---------- */
function toast(msg, kind = '') {
  const box = $('#toasts'); if (!box || !msg) return;
  while (box.children.length >= 2) box.firstElementChild.remove();
  const t = document.createElement('div'); t.className = 'toast ' + kind; t.textContent = msg; t.setAttribute('role', 'status');
  box.appendChild(t);
  setTimeout(() => t.classList.add('out'), 2300); setTimeout(() => t.remove(), 2800);
}
const Modal = {
  onClose: null,
  open(html, { label = '', cls = '', onClose = null } = {}) {
    const root = $('#modal');
    root.innerHTML = `<div class="mdl-back" data-act="ui.close"></div><div class="mdl ${cls}" role="dialog" aria-modal="true" aria-label="${esc(label)}"><button class="mdl-x icon-btn" data-act="ui.close" aria-label="سكّر">${ic('x')}</button>${html}</div>`;
    root.hidden = false; document.body.classList.add('no-scroll'); this.onClose = onClose;
    setTimeout(() => { const f = root.querySelector('[autofocus]') || root.querySelector('.mdl button:not(.mdl-x), .mdl input'); if (f) f.focus({ preventScroll: true }); }, 40);
  },
  close() {
    const root = $('#modal'); if (!root || root.hidden) return;
    root.hidden = true; root.innerHTML = ''; document.body.classList.remove('no-scroll');
    const cb = this.onClose; this.onClose = null; if (cb) cb();
  },
  isOpen() { const r = $('#modal'); return !!r && !r.hidden; },
};
function ask(title, body = '', yes = 'أكيد', no = 'لا، خلّيني') {
  return new Promise((res) => {
    UI._ask = res;
    Modal.open(`<h2 class="mdl-title">${esc(title)}</h2>${body ? `<p class="muted">${esc(body)}</p>` : ''}<div class="row end"><button class="btn ghost" data-act="ui.askNo">${esc(no)}</button><button class="btn primary" data-act="ui.askYes" autofocus>${esc(yes)}</button></div>`,
      { label: title, onClose: () => { const r = UI._ask; UI._ask = null; if (r) r(false); } });
  });
}
const reduced = () => !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
function celebrate(colors = ['saffron', 'pome', 'sky', 'mint', 'grape', 'rose']) {
  if (reduced()) return;
  const box = document.createElement('div'); box.className = 'confetti'; box.setAttribute('aria-hidden', 'true');
  let h = '';
  for (let i = 0; i < 110; i++) h += `<i style="left:${rnd(100)}%;background:var(--${pick(colors)});animation-duration:${(2.2 + Math.random() * 2.4).toFixed(2)}s;animation-delay:${(Math.random() * 0.6).toFixed(2)}s;transform:rotate(${rnd(360)}deg);border-radius:${pick(['2px', '50%'])}"></i>`;
  box.innerHTML = h; document.body.appendChild(box); setTimeout(() => box.remove(), 5400);
}
function burst(el, color = 'good') {
  if (!el || reduced()) return;
  const b = document.createElement('div'); b.className = 'burst'; b.style.cssText = cvar(color);
  let h = ''; for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2, r = 70 + rnd(60); h += `<i style="--bx:${Math.cos(a) * r}px;--by:${Math.sin(a) * r}px"></i>`; }
  b.innerHTML = h; el.style.position = el.style.position || 'relative'; el.appendChild(b); setTimeout(() => b.remove(), 800);
}
const Count = {
  seen: {},
  run() {
    $$('[data-count]').forEach((el) => {
      const k = el.dataset.count, to = +el.dataset.to, from = k in this.seen ? this.seen[k] : to; this.seen[k] = to;
      if (from === to || reduced()) { el.textContent = num(to); return; }
      const t0 = performance.now(), dur = 700;
      const step = (t) => { const p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 3); el.textContent = num(Math.round(from + (to - from) * e)); if (p < 1 && el.isConnected) requestAnimationFrame(step); };
      requestAnimationFrame(step);
    });
  },
};

/* ---------- shared party-game pieces ---------- */
const Party = {
  roster(min, max = 12) { const r = (Store.d.roster || []).slice(0, max); while (r.length < min) r.push(''); return r; },
  keep(list) { Store.d.roster = list.map((n) => (n || '').trim()).filter(Boolean).slice(0, 14); Store.soon(); },
  names(list) {
    const out = [];
    list.forEach((n, i) => { const base = (n || '').trim() || `لاعب ${i + 1}`; let v = base, k = 2; while (out.includes(v)) v = `${base} ${k++}`; out.push(v); });
    return out;
  },
  editor(ns, list, { min = 3, max = 12, ph = 'اسم اللاعب' } = {}) {
    const rows = list.map((n, i) => `<div class="roster-row"><span class="avatar sm" style="${cvar(PCOL[i % PCOL.length])}"><b class="av-l" id="${ns}-av${i}">${esc((n || '').trim() ? initial(n) : i + 1)}</b></span><input id="${ns}-p${i}" class="inp" maxlength="18" value="${esc(n)}" placeholder="${ph} ${i + 1}" data-in="${ns}.pname" data-i="${i}" data-enter="${ns}.padd" autocomplete="off" enterkeyhint="next"><button class="icon-btn" data-act="${ns}.pdel" data-i="${i}" aria-label="احذف ${esc(n || 'اللاعب')}" ${list.length <= min ? 'disabled' : ''}>${ic('x')}</button></div>`).join('');
    return `<div class="roster">${rows}</div><div class="row">${typeof Room !== 'undefined' && Room.role === 'host' && Room.players.length ? `<button class="btn sm" data-act="room.names" data-ns="${ns}" data-snd="select">${ic('smartphone')} أسماء الغرفة (${Room.players.length})</button>` : ''}${list.length < max ? `<button class="btn ghost sm" data-act="${ns}.padd">${ic('user-plus')} ضيف لاعب</button>` : ''}<span class="faint" style="font-size:var(--fs-sm)">${list.length} من ${max} · الأقل ${min}</span></div>`;
  },
  acts(ns, getList, { min = 3, max = 12 } = {}) {
    return {
      pname(d, el) { getList()[+d.i] = el.value; const av = $(`#${ns}-av${d.i}`); if (av) av.textContent = el.value.trim() ? initial(el.value) : +d.i + 1; },
      pdel(d) { const l = getList(); if (l.length > min) { l.splice(+d.i, 1); App.render(); } },
      padd() {
        const l = getList(); if (l.length >= max) return;
        l.push(''); App.render(); setTimeout(() => { const el = $(`#${ns}-p${l.length - 1}`); if (el) el.focus(); }, 30);
      },
    };
  },
  /* who: the player object (color + mascot) when there is one */
  handoff(name, act, color, note = 'ما حدا يطلّ على الشاشة غيره.', who = null) {
    const pic = who && who.color ? `<div class="handoff-pic">${avatar(who.color, who.name, 'xl')}${em('🤫', 'hush')}</div>` : em('🤫', 'float');
    return `<section class="handoff" style="${cvar(color)}">${pic}<p class="eyebrow">مرّروا الجهاز لـ</p><h2 class="handoff-name">${esc(name)}</h2><p class="muted">${esc(note)}</p><button class="btn c xl" data-act="${act}" data-snd="flip" autofocus>${ic('eye')} أنا ${esc(name)}، ورجيني</button></section>`;
  },
  board(players, { sub = null, tag = null } = {}) {
    const sorted = players.map((p, i) => ({ ...p, i })).sort((a, b) => b.score - a.score);
    const medal = (k, sc) => (sc > 0 && k < 3 ? em(['🥇', '🥈', '🥉'][k], '', '', '--s:1.6em') : k + 1);
    return `<ol class="rank">${sorted.map((p, k) => `<li style="${p.color ? cvar(p.color) : ''}"><span class="pos">${medal(k, p.score)}</span><span class="nm">${p.color ? avatar(p.color, p.name, 'sm') : ''}<span>${esc(p.name)}</span>${tag ? tag(p) : ''}</span>${sub ? `<span class="sub">${sub(p)}</span>` : ''}<span class="sc">${num(p.score)}</span></li>`).join('')}</ol>`;
  },
  /* players get the same color + mascot the roster editor showed them */
  dress(names) { return names.map((name, i) => ({ name, score: 0, color: PCOL[i % PCOL.length] })); },
  winners(players) { const m = Math.max(...players.map((p) => p.score)); return players.filter((p) => p.score === m); },
};

/* ---------- AI (the viewer's own Claude, through the sample capability) ---------- */
const AI = {
  fn: null,
  setState(s) { document.documentElement.dataset.ai = s; },
  async init() {
    this.setState('pending');
    try { if (window.claude && typeof window.claude.use === 'function') this.fn = (await window.claude.use('sample')) || null; } catch (e) { this.fn = null; }
    this.setState(this.fn ? 'on' : 'off');
  },
  async json(prompt, opts) { if (!this.fn) throw { code: 'unavailable' }; return this.fn.json(prompt, opts); },
  err(e) {
    const c = e && e.code;
    if (['not_granted', 'sampling_disabled', 'not_declared', 'capability_disabled', 'capability_removed', 'unavailable'].includes(c)) {
      this.fn = null; this.setState('off'); return 'الذكاء الاصطناعي مش متاح على هالجهاز.';
    }
    if (c === 'rate_limited') return 'كثرت الطلبات. استنوا شوي وجرّبوا كمان مرة.';
    if (c === 'session_expired') return 'لازم تسجّلوا دخول على Claude من جديد.';
    if (c === 'refused') return 'ما قدر يجاوب على هالطلب. غيّروا الصياغة وجرّبوا.';
    if (c === 'invalid_json' || c === 'empty_completion') return 'الرد ما زبط. جرّبوا كمان مرة.';
    if (c === 'cancelled') return '';
    return 'صار خلل بالاتصال. جرّبوا كمان مرة.';
  },
};

/* ---------- actions, screens, router ---------- */
const Acts = {};
const on = (ns, h) => { Acts[ns] = Object.assign(Acts[ns] || {}, h); };
const run = (spec, el, e) => {
  const [ns, fn] = String(spec).split('.');
  const h = Acts[ns] && Acts[ns][fn];
  if (!h) return false;
  try { const r = h(el.dataset, el, e); if (r && r.catch) r.catch((err) => { console.error(err); }); } catch (err) { console.error(err); toast('صار خطأ صغير. جرّبوا كمان مرة.', 'bad'); }
  return true;
};
document.addEventListener('click', (e) => {
  const el = e.target.closest('[data-act]');
  if (!el || el.disabled || el.getAttribute('aria-disabled') === 'true') return;
  e.preventDefault(); Sfx.play(el.dataset.snd || 'tap');
  run(el.dataset.act, el, e);
});
document.addEventListener('input', (e) => { const el = e.target.closest('[data-in]'); if (el) run(el.dataset.in, el, e); });
document.addEventListener('change', (e) => { const el = e.target.closest('[data-ch]'); if (el) run(el.dataset.ch, el, e); });
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && Modal.isOpen()) { Modal.close(); return; }
  if (e.key === 'Enter' && !e.isComposing) { const el = e.target.closest('[data-enter]'); if (el) { e.preventDefault(); run(el.dataset.enter, el, e); } }
});

const Screens = {};
const App = {
  cur: 'home', _silent: false,
  show(name, { push = true } = {}) {
    if (!Screens[name]) name = 'home';
    if (App.cur !== name) { const prev = Screens[App.cur]; if (prev && prev.leave) prev.leave(); }
    const mod = typeof GAME_MODS !== 'undefined' && GAME_MODS[name]; if (mod && mod.enter) mod.enter();
    App.cur = name;
    if (push) {
      const h = name === 'home' ? '' : name;
      if (location.hash.slice(1) !== h) { App._silent = true; try { if (h) location.hash = h; else history.replaceState(null, '', location.pathname + location.search); App._silent = !!h; } catch (e) { App._silent = false; } }
    }
    const go = () => { Modal.close(); App.render(); window.scrollTo(0, 0); };
    if (document.startViewTransition && !reduced() && App._shown) { try { document.startViewTransition(go); } catch (e) { go(); } } else go();
    App._shown = true;
  },
  /* while a card is being dragged the page waits, and draws once it's put down */
  hold: false, held: false,
  release() { App.hold = false; if (App.held) { App.held = false; App.render(); } },
  render() {
    if (App.hold) { App.held = true; return; }
    const s = Screens[App.cur] || Screens.home;
    $('#view').innerHTML = s.render();
    document.documentElement.toggleAttribute('data-stage', !!(s.stage && s.stage()));
    if (s.mount) s.mount();
    FS.dock();
    Timer.paint(); Count.run();
    if (typeof Room !== 'undefined') Room.afterRender();
    if (typeof YT !== 'undefined') YT.place();
    $$('.hdr-nav [data-nav]').forEach((b) => b.setAttribute('aria-current', b.dataset.nav === App.cur ? 'page' : 'false'));
    const v = $('#snd'); if (v) { v.innerHTML = ic(Store.d.prefs.sound ? 'volume-2' : 'volume-x'); v.setAttribute('aria-label', Store.d.prefs.sound ? 'اطفي الأصوات' : 'شغّل الأصوات'); }
  },
};
window.addEventListener('hashchange', () => {
  if (App._silent) { App._silent = false; return; }
  const h = location.hash.slice(1);
  const tj = typeof BG !== 'undefined' && BG.fromHash(h); if (tj) { App.show(tj, { push: false }); return; }
  App.show(Screens[h] ? h : 'home', { push: false });
});

/* ---------- full screen ----------
   Where the browser allows it (computers, Android, iPad) the button puts the whole page in full screen. An iPhone's
   browsers can't do that for a web page, so there the button shows how to add لمّات to the home screen, which opens it
   like an app with no browser bars; opened that way it already fills the screen, so the button isn't shown. */
const FS = {
  can() { const d = document; return !!(d.fullscreenEnabled || d.webkitFullscreenEnabled); },
  on() { const d = document; return !!(d.fullscreenElement || d.webkitFullscreenElement); },
  ios() { return /iPhone|iPod|iPad/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1); },
  home() { return (window.matchMedia && matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true; },
  shown() { return this.can() || (this.ios() && !this.home()); },
  async toggle() {
    if (!this.can()) { this.tip(); return; }
    const d = document, el = d.documentElement;
    try {
      if (this.on()) await (d.exitFullscreen || d.webkitExitFullscreen).call(d);
      else await (el.requestFullscreen || el.webkitRequestFullscreen).call(el, { navigationUI: 'hide' });
    } catch (e) { toast('المتصفح ما سمح بالشاشة الكاملة هلّق. جرّبوا كمان مرة.', 'bad'); }
    this.paint();
  },
  tip() {
    Modal.open(`<div class="stack fs-tip" style="${cvar('sky')}">
      <div class="mdl-hero">${em('📱', 'float')}<div><p class="eyebrow">شاشة كاملة عالآيفون</p><h2 class="mdl-title">ضيفوا لمّات عالشاشة الرئيسية</h2></div></div>
      <p class="muted">الآيفون ما بيسمح لأي موقع يفتح شاشة كاملة من المتصفح. بس لما تضيفوا لمّات عالشاشة الرئيسية، بتفتح زي التطبيق، عالشاشة كلها وبدون شريط المتصفح.</p>
      <ol class="howto-steps"><li><div><b>زر المشاركة</b><span>اضغطوا زر المشاركة (المربع اللي طالع منه سهم). إذا ما بيّن، اضغطوا ⋯ أول.</span></div></li><li><div><b>إضافة إلى الشاشة الرئيسية</b><span>انزلوا بالقائمة واختاروا «إضافة إلى الشاشة الرئيسية»، وبعدين «إضافة».</span></div></li><li><div><b>افتحوها من الأيقونة</b><span>من هلّق افتحوا لمّات من أيقونتها، وكل الألعاب بتصير عالشاشة كلها.</span></div></li></ol>
      <p class="notice">${ic('lightbulb')}<span>الأيقونة إلها حفظ لحالها، فالاسم والإعدادات بتختاروهم فيها من جديد أول مرة.</span></p>
      <button class="btn c block" data-act="ui.close">تمام</button></div>`, { label: 'شاشة كاملة عالآيفون' });
  },
  btn(cls = 'icon-btn') {
    if (!this.shown()) return '';
    const on = this.on(), t = on ? 'اطلعوا من الشاشة الكاملة' : 'شاشة كاملة';
    return `<button class="${cls} fs-btn" data-act="ui.fs" aria-pressed="${on}" aria-label="${t}" title="${t}">${ic(on ? 'minimize' : 'maximize')}</button>`;
  },
  paint() {
    const on = this.on(), t = on ? 'اطلعوا من الشاشة الكاملة' : 'شاشة كاملة';
    document.documentElement.toggleAttribute('data-fs', on);
    $$('.fs-btn').forEach((b) => { b.innerHTML = ic(on ? 'minimize' : 'maximize'); b.setAttribute('aria-pressed', String(on)); b.setAttribute('aria-label', t); b.title = t; });
  },
  /* a game screen without a bar that carries the button (a results page, say) gets one in the corner */
  dock() {
    const v = $('#view'); if (!v || !document.documentElement.hasAttribute('data-stage') || v.querySelector('.fs-btn')) return;
    v.insertAdjacentHTML('beforeend', this.btn('icon-btn fs-dock'));
  },
};
['fullscreenchange', 'webkitfullscreenchange'].forEach((ev) => document.addEventListener(ev, () => FS.paint()));

const UI = { _ask: null };
on('ui', {
  close() { Modal.close(); },
  askYes() { const r = UI._ask; UI._ask = null; Modal.onClose = null; Modal.close(); if (r) r(true); },
  askNo() { Modal.close(); },
  fs() { FS.toggle(); },
  sound() { Store.d.prefs.sound = !Store.d.prefs.sound; Store.save(); App.render(); if (Store.d.prefs.sound) Sfx.play('good'); },
  go(d) { App.show(d.to || 'home'); },
});

