      build: ([, k]) => { const c = CC[k]; return c && c.p > 0 && { q: `قديش عدد سكان ${c.n} تقريبًا؟`, a: `${fmtPop(c.p)} نسمة`, x: `تقدير البنك الدولي لسنة ${c.py}` }; },
