      build: ([, i]) => { const r = tb('city', T_CITIES)[+i], c = r && CC[r[1]]; return c && { q: /^(جزيرة|جزر) /.test(r[0]) ? `${r[0]}: تبع أي دولة؟` : `مدينة ${r[0]}: بأي دولة؟`, a: c.n }; },
