      build: ([, n]) => { n = +n; return okN(n) && !QDISPUTED.has(n) && { q: `${sname(n)}: مكية ولا مدنية؟`, o: ['مكية', 'مدنية'], ok: 'vs', a: SUR(n)[2] ? 'مكية' : 'مدنية' }; },
      count: () => 114 - QDISPUTED.size,
