        if (once && !TV.s && !(typeof ROOM_GAMES !== 'undefined' && ROOM_GAMES[App.cur] && GAME_MODS[App.cur] && GAME_MODS[App.cur].mod && GAME_MODS[App.cur].mod.s)) { Store.flush(); setTimeout(() => location.reload(), 400); }
        else toast('في نسخة أحدث من لمّات على التلفونات. حدّثوا هالصفحة، والغرفة واللعبة بيرجعوا مثل ما هم.', 'bad');
