const SL_DIE = { 1: [4], 2: [0, 8], 3: [0, 4, 8], 4: [0, 2, 6, 8], 5: [0, 2, 4, 6, 8], 6: [0, 2, 3, 5, 6, 8] };
const slDie = (d, cls = '') => `<div class="die ${cls} ${d ? '' : 'blank'}" role="img" aria-label="الزهر: ${d || '؟'}">${Array.from({ length: 9 }, (_, i) => `<i class="${d && SL_DIE[d].includes(i) ? 'on' : ''}"></i>`).join('')}</div>`;

BG.register({
  id: 'snakes', name: 'السلّم والحيّة', min: 2, max: 4, tag: 'زهر وحظ',
  pitch: 'ارمي الزهر واطلع على السلالم، وانتبه من الحيّات! أول واحد بيوصل 100 بالزبط بيربح.',
  init(seats) { return { pos: seats.map(() => 1), names: seats.map((s) => s.n), t: 0, d: 0, last: null, w: null, wait: 0, msg: '', six: 0 }; },
  turn: (st) => (st.w == null && !st.wait ? st.t : -1),
  valid: (st, seat, a) => a.t === 'roll' && st.w == null && !st.wait && st.t === seat,
  apply(st, seat) {
    const d = 1 + rnd(6), from = st.pos[seat], name = st.names[seat];
    st.d = d;
    if (from + d > 100) {
      st.last = { s: seat, from, mid: from, to: from, d, via: null };
      st.msg = `${name}: الزهر ${d}، والمطلوب ${100 - from} بالزبط عشان الـ100`;
      st.wait = 900;
    } else {
      const mid = from + d, to = SL_UP[mid] || SL_DOWN[mid] || mid, via = SL_UP[mid] ? 'l' : SL_DOWN[mid] ? 's' : null;
      st.pos[seat] = to; st.last = { s: seat, from, mid, to, d, via };
      st.msg = via === 'l' ? `${name}: الزهر ${d}، وسلّم من ${mid} لـ${to} 🪜` : via === 's' ? `${name}: الزهر ${d}، وحيّة من ${mid} لـ${to} 🐍` : `${name}: الزهر ${d}، على المربع ${to}`;
      st.wait = Math.min(2600, 420 + d * 170 + (via ? 900 : 0));
      if (to === 100) { st.w = seat; st.msg = `🏁 ${name} على الـ100!`; }
    }
    st.six = d === 6 && st.w == null ? st.six + 1 : 0;
    if (st.w == null) { if (d === 6 && st.six < 3) st.msg += '، والـ6 إلها رمية كمان 🎲'; else { st.six = 0; st.t = (seat + 1) % st.pos.length; } }
  },
  over: (st) => (st.w == null || st.wait ? null : { winners: [st.w], score: st.pos.slice() }),
  boardLabel: 'المربع',
  botDelay: () => 650,
  bot: () => ({ t: 'roll' }),
  view: (st) => st,
  chip: (v, i) => `<b class="bg-sc">${v.pos[i]}</b>`,
  render(v, ctx) {
    const cells = []; for (let row = 9; row >= 0; row--) for (let x = 0; x < 10; x++) { const k = row % 2 === 0 ? 9 - x : x, n = row * 10 + k + 1; cells.push(`<div class="sl-c ${(row + x) % 2 ? 'a' : 'b'} ${n === 100 ? 'goal' : ''} ${SL_UP[n] ? 'up' : ''} ${SL_DOWN[n] ? 'down' : ''}"><span>${n}</span>${n === 100 ? em('👑') : ''}</div>`); }
    const at = {}; v.pos.forEach((p, i) => { (at[p] = at[p] || []).push(i); });
    const OFF = [[0, 0], [-1.8, -1.6], [1.8, 1.6], [1.8, -1.6]];
    const toks = v.pos.map((p, i) => { const [x, y] = slXY(p), grp = at[p], k = grp.indexOf(i), o = grp.length > 1 ? OFF[(k + 1) % 4] : OFF[0]; const s = ctx.seats[i] || {}; return `<span class="sl-tok ${v.t === i && !ctx.over ? 'turn' : ''}" data-s="${i}" style="${cvar(s.c || BG_COL[i])};left:${x + o[0]}%;top:${y + o[1]}%"><b>${BG.ini(s)}</b></span>`; }).join('');
    const who = ctx.seats[v.t] || {};
    const act = ctx.over ? '' : ctx.canAct && !v.wait ? BG.btn({ t: 'roll' }, `${ic('dices')} ارمي الزهر`, 'btn primary xl sl-roll', 'data-snd="roll"') : `<p class="sl-wait">${v.wait ? '<i class="bg-dots"><b></b><b></b><b></b></i>' : `${who.k === 'bot' ? `${ic('bot')} ` : ''}دور ${esc(who.n || '')}<i class="bg-dots"><b></b><b></b><b></b></i>`}</p>`;
    return `<div class="sl-wrap"><div class="sl-board" dir="ltr"><div class="sl-cells">${cells.join('')}</div><svg class="sl-art" viewBox="0 0 100 100" aria-hidden="true">${slArt()}</svg><div class="sl-toks">${toks}</div></div>
      <aside class="sl-side">${slDie(v.d, 'big')}${act}<p class="sl-msg" aria-live="polite">${esc(v.msg || 'كل واحد بيرمي بدوره. السلالم بتطلّعك والحيّات بتنزّلك.')}</p></aside></div>`;
  },
  mount(v, ctx, fresh) {
    if (!fresh || !v.last || !v.wait) return;
    const L = v.last, die = $('.sl-side .die'); if (die) die.classList.add('roll');
    const tok = $(`.sl-tok[data-s="${L.s}"]`); if (!tok || typeof tok.animate !== 'function' || reduced()) return;
    const frames = []; const pt = (n) => { const [x, y] = slXY(n); return { left: `${x}%`, top: `${y}%` }; };
    const walk = []; for (let n = L.from; n <= L.mid; n++) walk.push(n);
    const total = (walk.length - 1) * 170 + (L.via ? 900 : 0) + 380;
    frames.push(Object.assign(pt(L.from), { offset: 0 }));
    walk.slice(1).forEach((n, i) => frames.push(Object.assign(pt(n), { offset: (380 + (i + 1) * 170) / total })));
    if (L.via) frames.push(Object.assign(pt(L.to), { offset: 1 }));
    else frames[frames.length - 1].offset = 1;
    try { tok.animate(frames, { duration: total, easing: 'linear' }); } catch (e) { /* old browser */ }
    setTimeout(() => Sfx.play(L.via === 'l' ? 'reward' : L.via === 's' ? 'bad' : 'tap'), Math.max(0, total - (L.via ? 850 : 120)));
  },
});

/* ---- g_estate.js ---- */
/* ============================== عقارات الأردن ==============================
   A property-trading board game round Jordan (an original take on the genre, with its own board and cards).
   32 squares: start (انطلاق, +200 every time you pass it), the lock-up (النظارة), a rest stop and «go to the
   lock-up», 16 landmarks in 6 colour groups, 4 ways to travel, electricity and water, two taxes, and two decks:
   حظّك and صندوق الحارة.
   Roll two dice and move. Land on something nobody owns and you may buy it. Land on someone's and pay rent: a
   landmark's rent doubles when its owner has the whole group, and grows with houses (up to 4, then a hotel), which
   you can only build on a whole group, evenly. Travel pays 25/50/100/200 by how many the owner has; electricity and
   water pay 4× the dice, or 10× with both. Doubles roll again; a third double in a row goes to the lock-up.
   In the lock-up: pay 50, use a «طلعة ببلاش» card, or try for doubles (after three tries you pay and go).
   Short of cash, houses are sold back at half price and landmarks mortgaged for half; if that still isn't enough
   you're out, and everything you own goes to whoever you owed. The last one standing wins, or, when the rounds run
   out, the richest (cash + what you own). */
const EST_GC = ['#9a5b34', '#36b5ea', '#e8478f', '#f6851f', '#e53945', '#3b39c8'];
