    if (m.hi < (m.lo === 1 ? 13 : 14)) return Object.assign({}, m, { hi: m.hi + 1, jr: m.hi + 1, cards: at(m.lo, m.hi + 1, m.hi + 1, [c]), pts: m.pts + hdRV(m.hi + 1) });
    if (m.lo > (m.hi === 14 ? 2 : 1)) return Object.assign({}, m, { lo: m.lo - 1, jr: m.lo - 1, cards: at(m.lo - 1, m.hi, m.lo - 1, [c]), pts: m.pts + hdRV(m.lo - 1) });
