const MY_E = { shoe: '👣', col: '🧵', hair: '💇', hand: '✋', h: '📏', acc: '🕶️' };
const MY_T = { shoe: 'طبعة حذاء', col: 'خيط قماش', hair: 'شعرة', hand: 'بصمات', h: 'كاميرا وشهود', acc: 'شي وقع' };
const MY_HERRINGS = [
  { e: '☕', title: 'فنجان قهوة', text: 'فنجان قهوة نص مشروب. طلع إنه الكل شرب قهوة اليوم، فما بيفيد بإشي.' },
  { e: '📱', title: 'رقم تلفون', text: 'ورقة عليها رقم تلفون… طلع رقم محل الفلافل اللي جنبنا.' },
  { e: '🔑', title: 'مفتاح', text: 'مفتاح على الأرض. الكل معه نسخة منه، فهاد مش دليل.' },
  { e: '🐈', title: 'آثار قطّة', text: 'آثار رجلين صغار… طلعت قطّة الحارة، بريئة!' },
  { e: '🧾', title: 'فاتورة', text: 'فاتورة قديمة من الشهر الماضي، ما إلها علاقة.' },
];
/* a case: suspects, a culprit, and clues that leave exactly one */
function myCase(diff, round, used) {
  const L = MY_LV[diff] || MY_LV.mid;
  const sceneOrder = shuffle(MY_SCENES.filter((s) => !used.includes(s.id))), scene = sceneOrder[0] || pick(MY_SCENES);
  for (let attempt = 0; attempt < 400; attempt++) {
    const roles = shuffle(scene.roles).slice(0, L.n), pools = { m: shuffle(MY_NAMES.m), f: shuffle(MY_NAMES.f) };
    const sus = roles.map(([role, g]) => ({ n: pools[g].pop(), role, g, h: rnd(3), col: rnd(MY_COL.length), acc: MY_ACC[rnd(4)], hand: Math.random() < 0.3 ? 'شمال' : 'يمين', shoe: g === 'f' ? 37 + rnd(6) : 40 + rnd(6), hair: rnd(MY_HAIR.length), skin: rnd(4) }));
    const sig = new Set(sus.map((s) => MY_KEYS.map((k) => s[k]).join('|'))); if (sig.size < sus.length) continue;
    const culprit = rnd(L.n), C = sus[culprit], clues = [];
    let R = sus.map((_, i) => i);
    for (const key of shuffle(MY_KEYS)) {
      if (R.length === 1) break;
      const forms = [];
      for (const op of L.ops) {
        if (op === 'is') forms.push({ key, op: 'is', val: C[key] });
        if (op === 'not' && key !== 'hand' && key !== 'shoe') {
          const vals = [...new Set(R.map((i) => sus[i][key]))].filter((x) => x !== C[key]);
          vals.forEach((val) => forms.push({ key, op: 'not', val }));
        }
        if (op === 'range' && key === 'shoe') {
          const lo = Math.min(...R.map((i) => sus[i].shoe)), hi = Math.max(...R.map((i) => sus[i].shoe));
          if (C.shoe > lo) forms.push({ key, op: 'ge', val: C.shoe - (Math.random() < 0.5 ? 0 : 1) });
          if (C.shoe < hi) forms.push({ key, op: 'le', val: C.shoe + (Math.random() < 0.5 ? 0 : 1) });
        }
      }
      /* the useful forms: they rule someone out, and not everyone at once if it can be helped */
      const scored = forms.map((f) => ({ f, out: R.filter((i) => !myFits(sus[i], f)).length })).filter((x) => x.out > 0 && myFits(C, x.f));
      if (!scored.length) continue;
      const gentle = scored.filter((x) => R.length - x.out >= 1 && (x.out <= Math.ceil(R.length / 2) || R.length <= 2));
      const ch = pick(gentle.length ? gentle : scored).f;
      clues.push(ch); R = R.filter((i) => myFits(sus[i], ch));
    }
    if (R.length !== 1 || clues.length < L.min || clues.length > 6) continue;
    const herrings = shuffle(MY_HERRINGS).slice(0, L.herrings).map((h) => Object.assign({ herring: true }, h));
    const spots = shuffle(scene.spots.map((_, i) => i));
    /* g: the order the clues were picked in, each ruling out someone the ones before it didn't */
    const all = shuffle(clues.map((c, g) => Object.assign({ g }, c)).concat(herrings)).map((c, k) => Object.assign({}, c, { spot: spots[k % spots.length] }));
    all.forEach((c) => { if (!c.herring) { c.e = MY_E[c.key]; c.title = MY_T[c.key]; } c.text = myText(c, scene.spots[c.spot]); });
    return { scene: scene.id, round, sus, culprit, clues: all, need: clues.length };
  }
  return null;
}
/* how the clues rule people out, in the order that tells the story best */
function myExplain(cs) {
  const order = cs.clues.map((c, k) => k).filter((k) => !cs.clues[k].herring).sort((a, b) => (cs.clues[a].g ?? a) - (cs.clues[b].g ?? b));
  let R = cs.sus.map((_, i) => i); const out = [];
  for (const k of order) { const c = cs.clues[k], gone = R.filter((i) => !myFits(cs.sus[i], c)); R = R.filter((i) => myFits(cs.sus[i], c)); out.push({ k, gone }); }
  return out;
}

/* ---------------- the bot detective ---------------- */
function myBot(st, me, lv) {
  const cs = st.case, open = st.open[me], R = myLeft(cs, open);
  const left = cs.clues.map((_, k) => k).filter((k) => !open.includes(k));
  if (R.length === 1) return { t: 'accuse', s: R[0] };
  if (!left.length) return { t: 'accuse', s: pick(R) };
  /* another detective close to it? then a bot may take its chance */
  const near = st.open.some((o, i) => i !== me && !st.out[i] && o.length >= cs.need - 1);
  const g = lv === 'easy' ? (R.length <= 3 ? 0.2 : 0.06) : lv === 'mid' ? (R.length === 2 ? (near ? 0.4 : 0.15) : 0) : (R.length === 2 && near ? 0.55 : 0);
  if (Math.random() < g) return { t: 'accuse', s: pick(R) };
  return { t: 'clue', k: pick(left) };
}

function myNewCase(st) {
  st.round++;
  const cs = myCase(st.diff, st.round, st.used);
  st.used.push(cs.scene); if (st.used.length >= MY_SCENES.length) st.used = [];
  Object.assign(st, { case: cs, open: Array.from({ length: st.n }, () => []), out: Array(st.n).fill(false), phase: 'play', solved: -1, res: null, last: null, wait: 0 });
  st.t = st.first = (st.first + 1) % st.n;
}
function myPass(st) {
  for (let k = 1; k <= st.n; k++) { const j = (st.t + k) % st.n; if (!st.out[j]) { st.t = j; return true; } }
  return false;
}

BG.register({
  id: 'mystery', name: 'مين المجرم؟', min: 1, max: 4, hidden: true, tag: 'تحقيق وألغاز',
  pitch: 'إشي اختفى بالحارة! افتح الأدلة، قارن المشتبه فيهم، واتّهم المجرم قبل غيرك. لحالك أو مع صحابك أو ضد محقّقين بوتات.',
  boardLabel: 'النقاط', againLabel: 'لعبة جديدة',
  opts: [
    { k: 'rounds', label: 'كم قضية؟', ic: 'repeat', options: [[1, 'قضية وحدة'], [3, '3'], [5, '5']], def: 3 },
    { k: 'diff', label: 'الصعوبة', ic: 'gauge', options: [['easy', 'سهل'], ['mid', 'وسط'], ['hard', 'صعب']], def: 'mid' },
  ],
  init(seats, o) {
    const n = seats.length, st = { n, names: seats.map((s) => s.n), rounds: +o.rounds || 3, diff: MY_LV[o.diff] ? o.diff : 'mid', round: 0, score: Array(n).fill(0), used: [], first: rnd(n) - 1 };
    if (st.first < -1) st.first = -1;
    myNewCase(st); return st;
  },
  turn: (st) => (st.wait || st.phase !== 'play' ? -1 : st.t),
  valid(st, seat, a) {
    if (!a) return false;
    if (a.t === 'next') return st.phase === 'done';
    if (st.wait || st.phase !== 'play' || seat !== st.t || st.out[seat]) return false;
    if (a.t === 'clue') return Number.isInteger(a.k) && a.k >= 0 && a.k < st.case.clues.length && !st.open[seat].includes(a.k);
    if (a.t === 'accuse') return Number.isInteger(a.s) && a.s >= 0 && a.s < st.case.sus.length;
    return false;
  },
  apply(st, seat, a) {
    if (a.t === 'next') { if (st.round >= st.rounds) { st.phase = 'over'; st.wait = 0; return; } myNewCase(st); return; }
    if (a.t === 'clue') {
      st.open[seat].push(a.k); st.last = { s: seat, k: 'clue', c: a.k };
      myPass(st); return;
    }
    const cs = st.case;
    if (a.s === cs.culprit) {
      const pts = 10 + 3 * Math.max(0, cs.clues.length - st.open[seat].length);
      st.score[seat] += pts; st.solved = seat;
      st.res = { by: seat, pts, s: a.s, opened: st.open[seat].length, need: cs.need };
      st.last = { s: seat, k: 'right', sus: a.s }; st.phase = 'done'; return;
    }
    st.out[seat] = true; st.last = { s: seat, k: 'wrong', sus: a.s };
    if (!myPass(st) || st.out.every(Boolean)) { st.res = { by: -1, s: a.s }; st.phase = 'done'; }
  },
  over(st) {
    if (st.phase !== 'over') return null;
    const hi = Math.max(...st.score);
    return { winners: st.n === 1 ? (hi > 0 ? [0] : []) : st.score.map((x, i) => (x === hi && hi > 0 ? i : -1)).filter((i) => i >= 0), score: st.score.slice(), text: `${st.rounds} ${st.rounds === 1 ? 'قضية' : 'قضايا'} · ${{ easy: 'سهل', mid: 'وسط', hard: 'صعب' }[st.diff]}` };
  },
  botDelay: (st) => 1500,
  bot: (st, me, lv) => myBot(st, me, lv),
  safe(st, me) { const left = st.case.clues.map((_, k) => k).filter((k) => !st.open[me].includes(k)); return left.length ? { t: 'clue', k: left[0] } : { t: 'accuse', s: myLeft(st.case, st.open[me])[0] || 0 }; },
  view(st, seat) {
    const cs = st.case, done = st.phase !== 'play', mine = seat >= 0 ? st.open[seat] : [];
    const v = { n: st.n, names: st.names, rounds: st.rounds, round: st.round, diff: st.diff, score: st.score, phase: st.phase, t: st.t, out: st.out, solved: st.solved, res: st.res, last: st.last, me: seat };
    v.case = {
      scene: cs.scene, sus: cs.sus, need: cs.need, culprit: done ? cs.culprit : -1,
      clues: cs.clues.map((c, k) => ({ k, e: c.e, title: c.title, spot: c.spot, herring: done ? !!c.herring : undefined, text: done || mine.includes(k) ? c.text : null })),
      explain: done ? myExplain(cs) : null,
    };
    v.mine = mine.slice(); v.counts = st.open.map((o) => o.length);
    return copy(v);
  },
  chip: (v, i) => (v.out[i] ? '<b class="bg-sc my-out">برّا</b>' : `<b class="bg-sc" title="أدلة فتحها">${ic('search')}${v.counts[i]}</b>`),
  render(v, ctx) { return MYUI.html(v, ctx, false); },
  mount(v, ctx, fresh) { MYUI.mount(v, ctx, fresh); },
});

/* ---------------- the screen: the case, the scene, the clues, the suspects ---------------- */
