    scene.fog = new T.Fog(0xd8f0e0, 32, 75);
    st.sun.position.set(6, 18, 9); const sc = st.sun.shadow.camera; sc.left = -8; sc.right = 8; sc.top = 8; sc.bottom = -8; sc.updateProjectionMatrix();
    /* the lawn, trees and bushes */
    scene.add(G3D.mesh(new T.CircleGeometry(48, 48), G3D.mat(0x8fd06a, { p: { roughness: 1 } }), { rot: [-Math.PI / 2, 0, 0], pos: [0, -0.42, 0], cast: false }));
    [[-8.2, -2.5, 1.5], [-8.6, 3.2, 1.2], [8.3, -3, 1.6], [8.0, 2.8, 1.25], [-6.4, -7.2, 1.8], [6.8, -7.0, 1.7], [-1.5, -8.6, 1.9], [2.6, -9.0, 1.5], [-11.5, -9.5, 2.3], [11.6, -9.5, 2.2]].forEach(([x, z, s], k) => scene.add(this.tree(st, x, z, s, k)));
    const bush = G3D.mat(0x4fb85e, { p: { roughness: 0.9, flatShading: true } }), flower = [0xff6b8a, 0xffd23f, 0xffffff, 0xb983ff];
    [[-6.6, 5.6], [6.7, 5.4], [-7.2, 0.4], [7.1, -0.4], [-4.6, -6.6], [4.4, -6.8]].forEach(([x, z], k) => {
      scene.add(G3D.mesh(new T.IcosahedronGeometry(0.55, 1), bush, { pos: [x, -0.2, z], scale: [1.3, 0.8, 1] }));
      for (let f = 0; f < 4; f++) scene.add(G3D.mesh(new T.SphereGeometry(0.08, 8, 6), G3D.mat(flower[(k + f) % 4]), { pos: [x + Math.cos(f * 1.7 + k) * 0.6, 0.1 + (f % 2) * 0.12, z + Math.sin(f * 1.7 + k) * 0.45] }));
    });
