    scene.add(G3D.mesh(G3D.rbox(10.7, 0.42, 10.7, 3, 0.22), G3D.mat(0x9a5a2a, { p: { roughness: 0.5 } }), { pos: [0, -0.22, 0] }));
    st.boardCanvas = document.createElement('canvas'); st.boardCanvas.width = st.boardCanvas.height = 2048;
    st.boardTex = new T.CanvasTexture(st.boardCanvas); st.boardTex.colorSpace = T.SRGBColorSpace; st.boardTex.anisotropy = st.renderer.capabilities.getMaxAnisotropy();
    scene.add(G3D.mesh(new T.PlaneGeometry(10, 10), new T.MeshStandardMaterial({ map: st.boardTex, roughness: 0.8 }), { rot: [-Math.PI / 2, 0, 0], pos: [0, 0.001, 0], cast: false }));
    this.drawBoard(st);
