    st.die = G3D.die(0.8); st.die.userData.size = 0.8; st.die.quaternion.copy(G3D.dieQuat(5, 0.5)); scene.add(st.die);
    st.tray = G3D.mesh(new T.CylinderGeometry(1.05, 1.15, 0.16, 40), G3D.mat(0x7c4dff, { phys: true, p: { roughness: 0.4 } })); scene.add(st.tray);
    this.dieAt(st, [6.3, 3.6]);
