    const list = v.pos.map((p, i) => { const s = ctx.seats[i] || {}; return `<li class="${v.t === i && !ctx.over ? 'on' : ''}" style="${cvar(s.c || BG_COL[i])}"><i class="dot"></i><b>${esc(s.n || '')}</b><span>${p}</span></li>`; }).join('');
